      "version": "Versi\u00f3n 1.0 \u2014 1 de agosto de 2026",
      "section1Title": "1. PARTES Y NATURALEZA DE LA RELACI\u00d3N",
      "section1Content": "Este acuerdo se celebra entre NELHEALTHCOACH LLC, con domicilio en 33450 Shifting Sands Trail, Cathedral City, CA 92234, Estados Unidos (en adelante, \u201cNELHEALTHCOACH\u201d o \u201cla Plataforma\u201d), y el asesor de salud que lo acepta (en adelante, el \u201cAsesor\u201d). El Asesor presta sus servicios como contratista independiente. Este acuerdo no crea una relaci\u00f3n laboral, de sociedad, agencia ni de franquicia. El Asesor no tiene exclusividad: puede prestar servicios a otros negocios, siempre que no utilice informaci\u00f3n confidencial de la Plataforma ni compita deslealmente con ella.",
      "section2Title": "2. SERVICIOS DEL ASESOR",
      "section2Content": "El Asesor se compromete a proporcionar servicios de coaching en salud y bienestar a los clientes que se le asignen a trav\u00e9s de su enlace exclusivo de la Plataforma, incluyendo:",
      "section2Items": [
        "Planes de acci\u00f3n personalizados para cada cliente.",
        "Sesiones de seguimiento mensuales por videollamada (60 minutos).",
        "Recursos educativos sobre nutrici\u00f3n y bienestar.",
        "Apoyo motivacional y seguimiento continuo.",
        "Revisi\u00f3n y ajuste de las recomendaciones generadas por la Plataforma antes de entregarlas al cliente.",
      ],
      "section3Title": "3. TARIFAS Y SUSCRIPCI\u00d3N",
      "section3Intro": "El acceso del Asesor a la Plataforma tiene un costo de",
      "section3Price": "$ {{amount}} USD mensuales. Los primeros 30 d\u00edas son gratuitos (per\u00edodo de prueba). El Asesor establece el precio de sus propias sesiones dentro de la Plataforma; NELHEALTHCOACH cobra al cliente a trav\u00e9s de Stripe y transfiere al Asesor la parte correspondiente mediante Stripe Connect.",
      "section3Items": [
        "El pago se realiza mediante suscripci\u00f3n mensual autom\u00e1tica.",
        "La suscripci\u00f3n se renueva cada mes hasta que sea cancelada.",
        "El Asesor puede cancelar en cualquier momento desde el portal de facturaci\u00f3n.",
        "Al cancelar, el Asesor conservar\u00e1 acceso hasta el final del per\u00edodo pagado.",
        "El Asesor debe mantener una cuenta de Stripe Connect activa para recibir sus pagos.",
      ],
      "section4Title": "4. OBLIGACIONES DEL ASESOR",
      "section4Intro": "El Asesor se compromete a:",
      "section4Items": [
        "Mantener la confidencialidad de todos los datos de los clientes.",
        "Proporcionar un ambiente profesional, respetuoso y de apoyo.",
        "Mantener l\u00edmites profesionales y \u00e9ticos en todo momento.",
        "Utilizar la Plataforma para todas las comunicaciones con clientes.",
        "Declarar con veracidad sus certificaciones, t\u00edtulos y experiencia; la falsedad en estas declaraciones es causa de terminaci\u00f3n inmediata.",
        "Cumplir con las leyes aplicables al ejercicio de su actividad en su jurisdicci\u00f3n.",
      ],
      "section5Title": "5. TRATAMIENTO DE DATOS DE CLIENTES",
      "section5Content": "Los datos personales y de salud de los clientes pertenecen a la Plataforma y al cliente. El Asesor los trata exclusivamente para prestar sus servicios, como encargado de tratamiento, siguiendo las instrucciones de NELHEALTHCOACH. Los clientes han consentido que sus datos sean analizados por servicios de inteligencia artificial de la Plataforma para generar recomendaciones; el Asesor debe revisar, validar y ajustar dichas recomendaciones antes de entregarlas, y no debe introducir datos de clientes en herramientas de IA externas no autorizadas.",
      "section6Title": "6. SEGURIDAD DE DATOS Y CIBERSEGURIDAD",
      "section6Intro": "El Asesor se compromete a:",
      "section6Items": [
        "No extraer, copiar ni descargar datos de clientes fuera de la Plataforma, salvo autorizaci\u00f3n expresa.",
        "Proteger sus credenciales de acceso y no compartirlas con terceros.",
        "Utilizar dispositivos y conexiones seguros.",
        "Informar a NELHEALTHCOACH de cualquier acceso no autorizado, brecha o p\u00e9rdida de datos en un plazo m\u00e1ximo de 72 horas.",
        "Responder por las filtraciones de datos causadas por su negligencia.",
      ],
      "section7Title": "7. PROPIEDAD INTELECTUAL",
      "section7Content": "Los materiales, metodolog\u00edas, contenidos y recursos de la Plataforma son propiedad de NELHEALTHCOACH y no pueden ser compartidos, reproducidos ni utilizados fuera de la Plataforma sin autorizaci\u00f3n expresa. Los contenidos creados por el Asesor con las herramientas de la Plataforma podr\u00e1n ser utilizados por esta para prestar y mejorar sus servicios.",
      "section8Title": "8. TERMINACI\u00d3N",
      "section8Content": "Cualquiera de las partes puede terminar este acuerdo con 7 d\u00edas de notificaci\u00f3n. Al terminar, el Asesor deber\u00e1 completar las sesiones ya pagadas por sus clientes activos o coordinarse con NELHEALTHCOACH para transferirlos a otro asesor. El Asesor cesar\u00e1 el uso de la Plataforma y devolver\u00e1 o eliminar\u00e1 cualquier dato de clientes en su poder, salvo obligaciones legales.",
      "section9Title": "9. LIMITACI\u00d3N DE RESPONSABILIDAD E INDEMNIZACI\u00d3N",
      "section9Content": "En la m\u00e1xima medida permitida por la ley, la responsabilidad total de NELHEALTHCOACH frente al Asesor se limitar\u00e1 al importe pagado por el Asesor en concepto de suscripci\u00f3n en los tres (3) meses anteriores a la reclamaci\u00f3n. En ning\u00fan caso NELHEALTHCOACH ser\u00e1 responsable de da\u00f1os indirectos, incidentales, especiales o consecuentes. El Asesor indemnizar\u00e1 a NELHEALTHCOACH frente a reclamaciones de terceros derivadas de su negligencia, del incumplimiento de este acuerdo o del ejercicio de su actividad profesional.",
      "section10Title": "10. SOLUCI\u00d3N DE CONTROVERSIAS Y LEY APLICABLE",
      "section10Content": "Las partes intentar\u00e1n resolver cualquier controversia mediante mediaci\u00f3n durante un plazo de 30 d\u00edas antes de iniciar acciones legales. Este acuerdo se regir\u00e1 por las leyes del estado de California, Estados Unidos, y cualquier disputa no resuelta por mediaci\u00f3n se someter\u00e1 a los tribunales del estado de California.",
      "section11Title": "11. NOTIFICACIONES, INTEGRIDAD Y VERSIONES",
      "section11Content": "Las notificaciones se realizar\u00e1n por correo electr\u00f3nico a las direcciones registradas por cada parte. Este acuerdo constituye el entendimiento \u00edntegro entre las partes sobre su objeto. NELHEALTHCOACH podr\u00e1 actualizar estos t\u00e9rminos publicando la nueva versi\u00f3n en la Plataforma; el uso continuado de la Plataforma tras la actualizaci\u00f3n implica su aceptaci\u00f3n.",
      "section12Title": "12. ACEPTACI\u00d3N",
