      "section1Title": "1. PARTIES ET NATURE DE LA RELATION",
      "section1Content": "Le pr\u00e9sent accord est conclu entre NELHEALTHCOACH LLC, dont le si\u00e8ge est situ\u00e9 au 33450 Shifting Sands Trail, Cathedral City, CA 92234, \u00c9tats-Unis (ci-apr\u00e8s \u00ab NELHEALTHCOACH \u00bb ou la \u00ab Plateforme \u00bb), et le conseiller en sant\u00e9 qui l\u2019accepte (ci-apr\u00e8s le \u00ab Conseiller \u00bb). Le Conseiller fournit ses services en tant que prestataire ind\u00e9pendant. Le pr\u00e9sent accord ne cr\u00e9e ni relation de travail, ni soci\u00e9t\u00e9, ni agence, ni franchise. Le Conseiller n\u2019est pas soumis \u00e0 une exclusivit\u00e9 : il peut fournir des services \u00e0 d\u2019autres entreprises, \u00e0 condition de ne pas utiliser les informations confidentielles de la Plateforme ni de lui faire une concurrence d\u00e9loyale.",
      "section2Title": "2. SERVICES DU CONSEILLER",
      "section2Content": "Le Conseiller s\u2019engage \u00e0 fournir des services de coaching en sant\u00e9 et bien-\u00eatre aux clients qui lui sont assign\u00e9s via son lien exclusif de la Plateforme, notamment :",
