      "section7Title": "7. PROPRI\u00c9T\u00c9 INTELLECTUELLE",
      "section7Content": "Les mat\u00e9riels, m\u00e9thodologies, contenus et ressources de la Plateforme appartiennent \u00e0 NELHEALTHCOACH et ne peuvent \u00eatre partag\u00e9s, reproduits ni utilis\u00e9s hors de la Plateforme sans autorisation expresse. Les contenus cr\u00e9\u00e9s par le Conseiller avec les outils de la Plateforme pourront \u00eatre utilis\u00e9s par celle-ci pour fournir et am\u00e9liorer ses services.",
      "section8Title": "8. R\u00c9SILIATION",
      "section8Content": "Chacune des parties peut r\u00e9silier le pr\u00e9sent accord moyennant un pr\u00e9avis de 7 jours. \u00c0 la r\u00e9siliation, le Conseiller doit terminer les s\u00e9ances d\u00e9j\u00e0 pay\u00e9es par ses clients actifs ou se coordonner avec NELHEALTHCOACH pour les transf\u00e9rer \u00e0 un autre conseiller. Le Conseiller cessera l\u2019utilisation de la Plateforme et restituera ou supprimera toute donn\u00e9e de clients en sa possession, sauf obligation l\u00e9gale.",
      "section9Title": "9. LIMITATION DE RESPONSABILIT\u00c9 ET INDEMNISATION",
      "section9Content": "Dans toute la mesure permise par la loi, la responsabilit\u00e9 totale de NELHEALTHCOACH envers le Conseiller sera limit\u00e9e au montant pay\u00e9 par le Conseiller au titre de l\u2019abonnement au cours des trois (3) mois pr\u00e9c\u00e9dant la r\u00e9clamation. En aucun cas NELHEALTHCOACH ne sera responsable des dommages indirects, accessoires, sp\u00e9ciaux ou cons\u00e9cutifs. Le Conseiller indemnisera NELHEALTHCOACH contre les r\u00e9clamations de tiers d\u00e9coulant de sa n\u00e9gligence, de la violation du pr\u00e9sent accord ou de l\u2019exercice de son activit\u00e9 professionnelle.",
      "section10Title": "10. R\u00c8GLEMENT DES DIFF\u00c9RENDS ET LOI APPLICABLE",
      "section10Content": "Les parties tenteront de r\u00e9soudre tout diff\u00e9rend par m\u00e9diation pendant une p\u00e9riode de 30 jours avant d\u2019engager une action en justice. Le pr\u00e9sent accord sera r\u00e9gi par les lois de l\u2019\u00c9tat de Californie, \u00c9tats-Unis, et tout diff\u00e9rend non r\u00e9solu par m\u00e9diation sera soumis aux tribunaux de l\u2019\u00c9tat de Californie.",
      "section11Title": "11. NOTIFICATIONS, INT\u00c9GRALIT\u00c9 ET VERSIONS",
      "section11Content": "Les notifications seront envoy\u00e9es par courrier \u00e9lectronique aux adresses enregistr\u00e9es par chaque partie. Le pr\u00e9sent accord constitue l\u2019int\u00e9gralit\u00e9 de l\u2019entente entre les parties sur son objet. NELHEALTHCOACH pourra mettre \u00e0 jour ces conditions en publiant la nouvelle version sur la Plateforme ; l\u2019utilisation continue de la Plateforme apr\u00e8s la mise \u00e0 jour implique leur acceptation.",
      "section12Title": "12. ACCEPTATION",
