      "section1Content": "Il presente accordo \u00e8 stipulato tra NELHEALTHCOACH LLC, con sede legale al 33450 Shifting Sands Trail, Cathedral City, CA 92234, Stati Uniti (di seguito \u201cNELHEALTHCOACH\u201d o la \u201cPiattaforma\u201d), e il consulente della salute che lo accetta (di seguito il \u201cConsulente\u201d). Il Consulente fornisce i propri servizi in qualit\u00e0 di contraente indipendente. Il presente accordo non crea un rapporto di lavoro subordinato, una societ\u00e0, un\u2019agenzia o una franchigia. Il Consulente non \u00e8 vincolato da esclusivit\u00e0: pu\u00f2 fornire servizi ad altre attivit\u00e0, purch\u00e9 non utilizzi informazioni riservate della Piattaforma n\u00e9 le faccia concorrenza sleale.",
