      "section5Content": "I dati personali e sanitari dei clienti appartengono alla Piattaforma e al cliente. Il Consulente li tratta esclusivamente per fornire i propri servizi, in qualit\u00e0 di responsabile del trattamento, seguendo le istruzioni di NELHEALTHCOACH. I clienti hanno acconsentito all\u2019analisi dei propri dati da parte dei servizi di intelligenza artificiale della Piattaforma per generare raccomandazioni; il Consulente deve esaminare, validare e adeguare tali raccomandazioni prima di consegnarle e non deve inserire dati dei clienti in strumenti di IA esterni non autorizzati.",
