      "section1Content": "Diese Vereinbarung wird geschlossen zwischen NELHEALTHCOACH LLC, mit Sitz in 33450 Shifting Sands Trail, Cathedral City, CA 92234, USA (nachfolgend \u201cNELHEALTHCOACH\u201d oder die \u201cPlattform\u201d), und dem Gesundheitsberater, der sie akzeptiert (nachfolgend der \u201cBerater\u201d). Der Berater erbringt seine Leistungen als unabh\u00e4ngiger Auftragnehmer. Diese Vereinbarung begr\u00fcndet kein Arbeits-, Gesellschafts-, Agentur- oder Franchiseverh\u00e4ltnis. Der Berater ist nicht exklusiv gebunden: Er darf anderen Unternehmen Leistungen erbringen, sofern er keine vertraulichen Informationen der Plattform verwendet oder diese unlauter konkurrenziert.",
      "section2Title": "2. LEISTUNGEN DES BERATERS",
      "section2Content": "Der Berater verpflichtet sich, \u00fcber seinen exklusiven Plattform-Link zugewiesenen Kunden Coaching-Dienstleistungen im Bereich Gesundheit und Wohlbefinden zu erbringen, einschlie\u00dflich:",
